import itertools

def is_well_formed(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for perm in itertools.permutations(lst):
        concat_str = ''.join(perm)
        if is_well_formed(concat_str):
            return 'Yes'

    return 'No'

